use crate::domain::{
    models::{
        declaration_resolution::{ComparisonRow, ScoredPair, ScoredPairs, ScoringInput},
        entity_ingestion::EntityIngestionError,
    },
    repositories::declaration_resolution::FunderScorer,
};
use duckdb::{Connection, params};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::sync::Arc;

const MODEL: &str = include_str!("../../../resources/funder-resolution/model.json");
const ARTIFACT: &str = include_str!("../../../resources/funder-resolution/artifact.json");
const SCHEMA: &str = include_str!("../../../resources/funder-resolution/schema.sql");
const COUNT: &str = include_str!("../../../resources/funder-resolution/count.sql");
const CONCAT: &str = include_str!("../../../resources/funder-resolution/concat.sql");
const CANDIDATES: &str = include_str!("../../../resources/funder-resolution/candidates.sql");
const PREDICT: &str = include_str!("../../../resources/funder-resolution/predict.sql");
const OUTPUT: &str = include_str!("../../../resources/funder-resolution/output.sql");

/// Executes the bundled frozen Splink program in a private embedded DuckDB connection.
pub struct DuckDbFunderScorer {
    model: Arc<FrozenModel>,
}

impl DuckDbFunderScorer {
    /// Loads the embedded model and verifies its generated SQL digests.
    ///
    /// # Errors
    /// Returns an error when the bundled model and generated program disagree.
    pub fn new() -> Result<Self, EntityIngestionError> {
        Ok(Self {
            model: Arc::new(FrozenModel::bundled()?),
        })
    }
}

impl FunderScorer for DuckDbFunderScorer {
    async fn score(&self, input: &ScoringInput) -> Result<ScoredPairs, EntityIngestionError> {
        let model = self.model.clone();
        let rows = input.rows.clone();
        let budget = input.candidate_budget;
        let (pairs, metadata) = tokio::task::spawn_blocking(move || {
            let (pairs, version) = model.execute(&rows, budget)?;
            Ok::<_, EntityIngestionError>((pairs, model.provenance(version)?))
        })
        .await
        .map_err(scoring_error)??;
        ScoredPairs::checked(pairs, metadata, input)
    }
}

struct FrozenModel {
    parameters: ModelParameters,
    artifact: GeneratedArtifact,
}

#[derive(Deserialize)]
struct ModelParameters {
    model_version: String,
    splink_version: String,
    duckdb_version: String,
    calibrated: bool,
    settings: serde_json::Value,
}

#[derive(Deserialize)]
struct GeneratedArtifact {
    format_version: u32,
    model_sha256: String,
    sql_sha256: String,
    generator: Generator,
}

#[derive(Deserialize, Serialize)]
struct Generator {
    splink_version: String,
    duckdb_version: String,
}

#[derive(Serialize)]
struct ModelProvenance<'a> {
    backend: &'static str,
    model_version: &'a str,
    duckdb_version: String,
    calibrated: bool,
    settings: &'a serde_json::Value,
    generator: &'a Generator,
    model_sha256: &'a str,
    sql_sha256: &'a str,
}

impl FrozenModel {
    fn bundled() -> Result<Self, EntityIngestionError> {
        let parameters: ModelParameters = serde_json::from_str(MODEL).map_err(scoring_error)?;
        let artifact: GeneratedArtifact = serde_json::from_str(ARTIFACT).map_err(scoring_error)?;
        let mut sql_digest = Sha256::new();
        for (index, sql) in [SCHEMA, COUNT, CONCAT, CANDIDATES, PREDICT, OUTPUT]
            .into_iter()
            .enumerate()
        {
            if index > 0 {
                sql_digest.update(b"\0");
            }
            sql_digest.update(sql.as_bytes());
        }
        if artifact.format_version != 1
            || artifact.model_sha256 != format!("{:x}", Sha256::digest(MODEL.as_bytes()))
            || artifact.sql_sha256 != format!("{:x}", sql_digest.finalize())
            || artifact.generator.splink_version != parameters.splink_version
            || artifact.generator.duckdb_version != parameters.duckdb_version
        {
            return Err(scoring_error(
                "frozen model or SQL changed; regenerate with resolution/generate.py",
            ));
        }
        Ok(Self {
            parameters,
            artifact,
        })
    }

    fn execute(
        &self,
        rows: &[ComparisonRow],
        budget: usize,
    ) -> Result<(Vec<ScoredPair>, String), EntityIngestionError> {
        let connection = Connection::open_in_memory().map_err(scoring_error)?;
        let version = connection.version().map_err(scoring_error)?;
        let version = version.strip_prefix('v').unwrap_or(&version).to_owned();
        if version != self.parameters.duckdb_version {
            return Err(scoring_error(format!(
                "frozen SQL requires DuckDB {}; found {version}",
                self.parameters.duckdb_version
            )));
        }
        connection.execute_batch(SCHEMA).map_err(scoring_error)?;
        {
            let mut profiles = connection
                .prepare("INSERT INTO profile_rows VALUES (?, ?, ?, ?)")
                .map_err(scoring_error)?;
            let mut keys = connection
                .prepare("INSERT INTO profile_blocking_keys VALUES (?, ?, ?)")
                .map_err(scoring_error)?;
            for row in rows {
                profiles
                    .execute(params![
                        row.key,
                        row.name,
                        row.address,
                        row.needs_resolution
                    ])
                    .map_err(scoring_error)?;
                for (ordinal, key) in row.blocking_keys.iter().enumerate() {
                    keys.execute(params![row.key, ordinal, key])
                        .map_err(scoring_error)?;
                }
            }
        }
        let count: usize = connection
            .query_row(COUNT, [], |row| row.get(0))
            .map_err(scoring_error)?;
        if count > budget {
            return Err(scoring_error(format!(
                "candidate budget {budget} exceeded by {count} profile pairs; raise candidate_budget explicitly"
            )));
        }
        let mut pairs = Vec::new();
        if count > 0 {
            for sql in [CONCAT, CANDIDATES, PREDICT] {
                connection.execute_batch(sql).map_err(scoring_error)?;
            }
            let mut statement = connection.prepare(OUTPUT).map_err(scoring_error)?;
            let scored = statement
                .query_map([], |row| {
                    Ok(ScoredPair {
                        left: row.get(0)?,
                        right: row.get(1)?,
                        probability: row.get(2)?,
                        name_level: row.get(3)?,
                        address_level: row.get(4)?,
                    })
                })
                .map_err(scoring_error)?;
            for pair in scored {
                pairs.push(pair.map_err(scoring_error)?);
            }
        }
        if pairs.len() != count {
            return Err(scoring_error(
                "frozen SQL did not return every generated candidate",
            ));
        }
        Ok((pairs, version))
    }

    fn provenance(&self, version: String) -> Result<serde_json::Value, EntityIngestionError> {
        serde_json::to_value(ModelProvenance {
            backend: "duckdb",
            model_version: &self.parameters.model_version,
            duckdb_version: version,
            calibrated: self.parameters.calibrated,
            settings: &self.parameters.settings,
            generator: &self.artifact.generator,
            model_sha256: &self.artifact.model_sha256,
            sql_sha256: &self.artifact.sql_sha256,
        })
        .map_err(scoring_error)
    }
}

fn scoring_error(error: impl std::fmt::Display) -> EntityIngestionError {
    EntityIngestionError::DataError(format!("DuckDB funder scoring failed: {error}"))
}

#[cfg(test)]
mod tests;
use super::*;
use crate::domain::models::declaration_resolution::ResolutionInput;
use std::collections::BTreeMap;

#[derive(Deserialize)]
struct Reference {
    cases: Vec<ReferenceCase>,
}

#[derive(Deserialize)]
struct ReferenceCase {
    name: String,
    rows: Vec<ComparisonRow>,
    pairs: Vec<ScoredPair>,
}

fn reference() -> Reference {
    serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/funder-resolution.json"
    )))
    .unwrap()
}

#[test]
fn native_duckdb_matches_original_splink_candidates_levels_and_probabilities() {
    let model = FrozenModel::bundled().unwrap();
    for mut case in reference().cases {
        for _ in 0..2 {
            let (actual, version) = model
                .execute(&case.rows, case.pairs.len().max(1))
                .unwrap_or_else(|error| panic!("{}: {error}", case.name));
            assert_eq!(version, "1.4.4");
            assert_eq!(actual.len(), case.pairs.len(), "{}", case.name);
            for (actual, expected) in actual.iter().zip(&case.pairs) {
                assert_eq!(actual.left, expected.left, "{}", case.name);
                assert_eq!(actual.right, expected.right, "{}", case.name);
                assert_eq!(actual.name_level, expected.name_level, "{}", case.name);
                assert_eq!(
                    actual.address_level, expected.address_level,
                    "{}",
                    case.name
                );
                assert!(
                    (actual.probability - expected.probability).abs()
                        <= expected.probability.abs() * 1e-12,
                    "{} pair {} / {}: {} != {}",
                    case.name,
                    actual.left,
                    actual.right,
                    actual.probability,
                    expected.probability
                );
            }
            case.rows.reverse();
        }
    }
}

#[test]
fn candidate_budget_refuses_the_complete_count_instead_of_truncating() {
    let model = FrozenModel::bundled().unwrap();
    let case = reference()
        .cases
        .into_iter()
        .find(|case| case.name == "overlapping_rules")
        .unwrap();
    let error = model.execute(&case.rows, 2).err().unwrap().to_string();
    assert!(error.contains("candidate budget 2 exceeded by 3 profile pairs"));
    assert_eq!(model.execute(&case.rows, 3).unwrap().0.len(), 3);
}

#[tokio::test]
async fn scorer_returns_checked_empty_scores_with_actual_native_provenance() {
    let input = ResolutionInput::new(vec![], vec![], BTreeMap::new()).unwrap();
    let input = input.scoring_input(10);
    let scorer = DuckDbFunderScorer::new().unwrap();
    let (first, second) = tokio::join!(scorer.score(&input), scorer.score(&input));
    let scores = first.unwrap();
    assert!(scores.pairs.is_empty());
    assert_eq!(scores.model, second.unwrap().model);
    assert_eq!(scores.model["backend"], "duckdb");
    assert_eq!(scores.model["duckdb_version"], "1.4.4");
    assert_eq!(scores.model["generator"]["splink_version"], "4.0.17");
    assert_eq!(scores.model["model_version"], "funder-frozen-v2");
    assert_eq!(scores.model["calibrated"], false);
    assert_eq!(scores.model["sql_sha256"].as_str().unwrap().len(), 64);
    assert!(scores.model.get("python_version").is_none());
    assert!(scores.model.get("splink_version").is_none());
}
"""Regenerate the frozen DuckDB program and independent Splink reference scores."""

import argparse
from copy import deepcopy
import hashlib
import importlib.metadata
import json
from pathlib import Path
import re

import duckdb
from splink import DuckDBAPI, Linker


ROOT = Path(__file__).resolve().parents[1]
BUNDLE = ROOT / "exposed/resources/funder-resolution"
REFERENCE = ROOT / "exposed/tests/fixtures/funder-resolution.json"
SQL_FILES = ("schema.sql", "count.sql", "concat.sql", "candidates.sql", "predict.sql", "output.sql")
STAGES = ("__splink__df_concat_with_tf", "__splink__blocked_id_pairs", "__splink__df_predict")
SCHEMA = '''CREATE TABLE profile_rows (
    "key" VARCHAR PRIMARY KEY,
    name VARCHAR NOT NULL,
    address VARCHAR,
    needs_resolution BOOLEAN NOT NULL
);
CREATE TABLE profile_blocking_keys (
    profile_key VARCHAR NOT NULL,
    ordinal UINTEGER NOT NULL,
    blocking_key VARCHAR NOT NULL
);
CREATE VIEW profiles AS
SELECT p."key", p.name, p.address,
       coalesce(
           (SELECT list(k.blocking_key ORDER BY k.ordinal)
            FROM profile_blocking_keys k WHERE k.profile_key = p."key"),
           []::VARCHAR[]
       ) AS blocking_keys,
       p.needs_resolution
FROM profile_rows p;
'''
OUTPUT = '''SELECT key_l, key_r, match_probability, gamma_name, gamma_address
FROM __splink__df_predict
ORDER BY key_l, key_r;
'''


def row(key, name, address=None, needs_resolution=True, blocking_keys=()):
    return dict(key=key, name=name, address=address,
                needs_resolution=needs_resolution, blocking_keys=list(blocking_keys))


def cases():
    levels = [row(f"{name_index}-{address_index}", name, address, blocking_keys=["all-levels"])
              for name_index, name in enumerate(("john smith", "jon smith", "different organisation"))
              for address_index, address in enumerate(("1 road", "2 road", None))]
    return [
        ("empty", []),
        ("singleton", [row("a", "john smith")]),
        ("comparison_levels", levels),
        ("exact_fuzzy_missing", [row("a", "john smith", "1 road"), row("b", "john smith", "1 road"),
                                  row("c", "jon smith", "1 road"), row("d", "john smith")]),
        ("exact_name", [row("a", "same name"), row("b", "same name")]),
        ("exact_address", [row("a", "alpha", "1 road"), row("b", "zulu", "1 road")]),
        ("three_character_prefix", [row("a", "example charity"), row("b", "example foundation")]),
        ("initial_surname", [row("a", "john smith"), row("b", "jon smith"), row("c", "james smyth")]),
        ("anchored_profiles", [row("a", "acme", "1 road", False), row("b", "acme", "1 road", False),
                               row("c", "acme", "1 road")]),
        ("only_anchors", [row("a", "acme", "1 road", False), row("b", "acme", "1 road", False)]),
        ("trade_union", [row("a", "unite union", blocking_keys=["trade-union:unite"]),
                          row("b", "east midlands unite the union", blocking_keys=["trade-union:unite"]),
                          row("c", "united against hunger")]),
        ("alias", [row("a", "northstar consulting trading as fletchers", blocking_keys=["funder-name:fletchers"]),
                    row("b", "fletchers", blocking_keys=["funder-name:fletchers"])]),
        ("generic_suffix", [row("a", "alpha ltd"), row("b", "amber ltd")]),
        ("suffix_on_left", [row("a", "amy company"), row("b", "ann collins")]),
        ("suffix_on_right", [row("a", "ann collins"), row("b", "amy company")]),
        ("empty_regex_match", [row("a", "alpha!"), row("b", "amber?")]),
        ("short_names", [row("a", "a"), row("b", "ab"), row("c", "ác")]),
        ("unicode", [row("a", "éva smith", "1 road"), row("b", "eva smith", "1 road"),
                      row("c", "伊藤", blocking_keys=["unicode"]), row("d", "伊東", blocking_keys=["unicode"])]),
        ("escaped_keys", [row("a", "alpha", blocking_keys=['quote"', "line\nbreak", "slash\\", "éva", "éva"]),
                           row("b", "zulu", blocking_keys=["line\nbreak", "slash\\", "éva"])]),
        ("escaped_key_collisions", [row("a", "alpha", blocking_keys=["line\nbreak"]),
                                     row("b", "zulu", blocking_keys=["linenbreak"]),
                                     row("c", "omega", blocking_keys=["line\\nbreak"]),
                                     row("d", "beta", blocking_keys=["line\nbreak"])]),
        ("repeated_profile", [row("profile-00000000", "same", "same"),
                               row("profile-00000000-repeat", "same", "same")]),
        ("overlapping_rules", [row(key, "same", "same", blocking_keys=["same"]) for key in ("a", "b", "c")]),
    ]


def count_sql(model):
    rules = " OR ".join(f"({rule})" for rule in model["settings"]["blocking_rules_to_generate_predictions"])
    return f'SELECT count(*) FROM profiles l JOIN profiles r ON l."key" < r."key" AND ({rules});\n'


def original_prediction(model, rows, capture=False):
    statements = []

    class CapturingAPI(DuckDBAPI):
        def _execute_sql_against_backend(self, sql):
            if sql.lstrip().upper().startswith("CREATE TABLE"):
                statements.append(sql)
            return super()._execute_sql_against_backend(sql)

    with duckdb.connect(":memory:") as connection:
        connection.execute('CREATE TABLE profiles ("key" VARCHAR, name VARCHAR, address VARCHAR, blocking_keys VARCHAR[], needs_resolution BOOLEAN)')
        if rows:
            connection.executemany("INSERT INTO profiles VALUES (?, ?, ?, ?, ?)",
                                   [(r["key"], r["name"], r["address"], r["blocking_keys"], r["needs_resolution"]) for r in rows])
        count = connection.execute(count_sql(model)).fetchone()[0]
        pairs = []
        if count:
            linker = Linker("profiles", deepcopy(model["settings"]), db_api=CapturingAPI(connection=connection))
            prediction = linker.inference.predict(threshold_match_probability=0.0)
            pairs = [dict(left=r["key_l"], right=r["key_r"], probability=r["match_probability"],
                          name_level=r["gamma_name"], address_level=r["gamma_address"])
                     for r in prediction.as_record_dict()]
        if len(pairs) != count:
            raise RuntimeError("original Splink candidate cardinality differs from worker count")
    if capture and len(statements) != len(STAGES):
        raise RuntimeError(f"expected three generated stages, found {len(statements)}")
    return sorted(pairs, key=lambda p: (p["left"], p["right"])), statements


def normalize(statements):
    names = {}
    for statement, expected in zip(statements, STAGES, strict=True):
        match = re.match(r"\s*CREATE TABLE\s+(\w+)\s+AS\b", statement, re.IGNORECASE)
        if match is None or not match[1].startswith(expected + "_"):
            raise RuntimeError(f"unexpected generated stage {expected}")
        names[match[1]] = expected
    normalized = []
    for statement in statements:
        for physical, stable in names.items():
            statement = re.sub(rf"\b{re.escape(physical)}\b", stable, statement)
        normalized.append(statement.strip().rstrip(";") + ";\n")
    return normalized


def replay(program, rows, expected):
    with duckdb.connect(":memory:") as connection:
        connection.execute(program["schema.sql"])
        for r in rows:
            connection.execute("INSERT INTO profile_rows VALUES (?, ?, ?, ?)",
                               [r["key"], r["name"], r["address"], r["needs_resolution"]])
            for ordinal, key in enumerate(r["blocking_keys"]):
                connection.execute("INSERT INTO profile_blocking_keys VALUES (?, ?, ?)", [r["key"], ordinal, key])
        count = connection.execute(program["count.sql"]).fetchone()[0]
        actual = []
        if count:
            for stage in ("concat.sql", "candidates.sql", "predict.sql"):
                connection.execute(program[stage])
            actual = [dict(left=r[0], right=r[1], probability=r[2], name_level=r[3], address_level=r[4])
                      for r in connection.execute(program["output.sql"]).fetchall()]
        if count != len(expected) or actual != expected:
            raise RuntimeError(f"SQL replay differs from original Splink: {actual!r} != {expected!r}")


def render(model):
    if importlib.metadata.version("splink") != model["splink_version"] or duckdb.__version__ != model["duckdb_version"]:
        raise RuntimeError("install the pinned resolution/requirements.txt generator dependencies")
    _, statements = original_prediction(model, cases()[3][1], capture=True)
    concat, candidates, predict = normalize(statements)
    program = dict(zip(SQL_FILES, (SCHEMA, count_sql(model), concat, candidates, predict, OUTPUT), strict=True))
    fixtures = []
    for name, rows in cases():
        expected, _ = original_prediction(model, rows)
        replay(program, rows, expected)
        fixtures.append(dict(name=name, rows=rows, pairs=expected))
    metadata = dict(format_version=1, model_sha256=hashlib.sha256((BUNDLE / "model.json").read_bytes()).hexdigest(),
                    sql_sha256=hashlib.sha256(b"\0".join(program[f].encode() for f in SQL_FILES)).hexdigest(),
                    generator=dict(splink_version=model["splink_version"], duckdb_version=model["duckdb_version"]))
    files = {BUNDLE / name: content for name, content in program.items()}
    files[BUNDLE / "artifact.json"] = json.dumps(metadata, indent=2, ensure_ascii=False, allow_nan=False) + "\n"
    files[REFERENCE] = json.dumps(dict(generator=metadata["generator"], cases=fixtures), indent=2, ensure_ascii=False, allow_nan=False) + "\n"
    return files


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="refuse if checked-in SQL or reference fixtures differ")
    options = parser.parse_args()
    model = json.loads((BUNDLE / "model.json").read_text())
    files = render(model)
    differences = [str(path.relative_to(ROOT)) for path, content in files.items()
                   if not path.is_file() or path.read_text() != content]
    if options.check and differences:
        raise SystemExit("generated resolution artifacts differ: " + ", ".join(differences))
    if not options.check:
        for path, content in files.items():
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content)
    print(f"{'Checked' if options.check else 'Generated'} frozen SQL and {len(cases())} original-Splink reference cases")


if __name__ == "__main__":
    main()

